(() => {
'use strict';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const menu=$('.menu-toggle'),mobile=$('#mobile-menu');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Open menu':'Close menu');mobile.hidden=open;});
addEventListener('keydown',e=>{if(e.key==='Escape'&&mobile&&!mobile.hidden){mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');menu.focus();}});
// The search index contains only content already published by this website.
const searchDialog=$('.search-dialog'),searchInput=$('#site-search'),searchResults=$('#search-results');
let index=[];try{index=JSON.parse($('#search-index')?.textContent||'[]');}catch{}
const renderSearch=()=>{if(!searchResults)return;const q=searchInput.value.trim().toLowerCase();const hits=index.filter(x=>!q||`${x.title} ${x.description}`.toLowerCase().includes(q)).slice(0,9);searchResults.replaceChildren();if(!hits.length){const p=document.createElement('p');p.className='caption';p.textContent='No matches. Try “automation”, “studio” or a project name.';searchResults.append(p);}for(const hit of hits){const a=document.createElement('a');a.className='search-result';a.href=hit.url;const name=document.createElement('strong'),type=document.createElement('span');name.textContent=hit.title;type.textContent=hit.type;a.append(name,type);searchResults.append(a);}};
searchDialog?.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();searchDialog.close();}});
const openSearch=()=>{if(!searchDialog)return;searchDialog.showModal();renderSearch();searchInput.focus();};
$$('[data-search-open]').forEach(b=>b.addEventListener('click',openSearch));$('[data-search-close]')?.addEventListener('click',()=>searchDialog.close());searchDialog?.addEventListener('click',e=>{if(e.target===searchDialog){const r=searchDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)searchDialog.close();}});searchInput?.addEventListener('input',renderSearch);
addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(searchDialog?.open)searchDialog.close();else openSearch();}});
// Sample workspace data never leaves the browser.
const datasets={operations:{title:'Operations overview',labels:['Revenue this month','Active projects','Tasks on track'],metrics:['$24,860','12','94%'],chart:'Revenue overview',rows:['Northline · Quote review','Aster · Project handover'],heading:'Today’s priorities',states:['Ready','In progress']},growth:{title:'Growth overview',labels:['Qualified enquiries','Campaigns in review','Cost per enquiry'],metrics:['48','4','$36'],chart:'Qualified enquiries',rows:['Search · Landing page review','Content · Next field note'],heading:'Marketing priorities',states:['Ready','In review']},ai:{title:'Automation overview',labels:['Sample runs','Awaiting approval','Exceptions queued'],metrics:['128','3','2'],chart:'Completed workflow runs',rows:['Enquiry · Response draft','Document · Missing field'],heading:'Review queue',states:['Review','Needs context']}};
$$('[data-dashboard]').forEach(root=>{
 const tabs=$$('[data-dash-tab]',root);const activate=(mode,focus=false)=>{const d=datasets[mode];if(!d)return;tabs.forEach(t=>{const on=t.dataset.dashTab===mode;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;if(on&&focus)t.focus();});$('[role=tabpanel]',root)?.setAttribute('aria-labelledby','tab-'+mode);$('[data-dash-title]',root).textContent=d.title;d.labels.forEach((v,i)=>$(`[data-metric-label="${i}"]`,root).textContent=v);d.metrics.forEach((v,i)=>$(`[data-metric="${i}"]`,root).textContent=v);$('[data-chart-title]',root).textContent=d.chart;$('[data-record-heading]',root).textContent=d.heading;d.rows.forEach((v,i)=>{$(`[data-record="${i}"]`,root).textContent=v;$(`[data-record-status="${i}"]`,root).textContent=d.states[i];});const points={operations:'M0 110 65 96 130 102 195 68 260 78 325 44 390 57 455 22 520 29 600 5',growth:'M0 114 65 112 130 90 195 98 260 69 325 77 390 40 455 49 520 28 600 10',ai:'M0 105 65 105 130 80 195 80 260 55 325 55 390 30 455 30 520 12 600 12'}[mode];$('.chart-line',root).setAttribute('d',points);$('.chart-fill',root).setAttribute('d',points+'V130H0Z');$('.dash-chart svg',root).setAttribute('aria-label',`Illustrative ${d.chart.toLowerCase()} trend using sample data`);};
 tabs.forEach((t,i)=>{t.addEventListener('click',()=>activate(t.dataset.dashTab));t.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();activate(tabs[next].dataset.dashTab,true);});});activate(root.dataset.startMode||'operations');
});
$$('[data-project-filter]').forEach(button=>button.addEventListener('click',()=>{$$('[data-project-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$$('[data-category]').forEach(c=>c.hidden=button.dataset.projectFilter!=='All'&&c.dataset.category!==button.dataset.projectFilter);}));
const articleSearch=$('#article-search');articleSearch?.addEventListener('input',()=>{const q=articleSearch.value.trim().toLowerCase();let count=0;$$('[data-search-text]').forEach(a=>{a.hidden=!a.dataset.searchText.toLowerCase().includes(q);if(!a.hidden)count++;});$('[data-article-count]').textContent=`${count} field note${count===1?'':'s'}`;$('.empty-state').hidden=count!==0;});
$$('[data-billing]').forEach(button=>button.addEventListener('click',()=>{const annual=button.dataset.billing==='annual';$$('[data-billing]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$$('[data-price]').forEach(p=>p.textContent=Number(p.dataset.price)*(annual?12:1));$$('[data-period]').forEach(p=>p.textContent=annual?'/year':'/month');}));
const serviceData={os:['Collective OS','CRM, finance, projects and people, connected around your operation.'],ai:['Collective AI','Useful agents and workflows that keep people in control.'],studio:['Collective Studio','Thoughtful websites, brands and custom software.'],growth:['Collective Growth','Search, content and conversion connected to the enquiry.'],academy:['Collective Academy','Practical training and capability that stays with your team.'],talent:['Collective Talent','Clear roles, visible capability and better collaboration.']};
$('.service-finder')?.addEventListener('change',e=>{const d=serviceData[e.target.value];if(!d)return;$('[data-finder-name]').textContent=d[0];$('[data-finder-copy]').textContent=d[1];$('[data-finder-link]').href='/services/'+e.target.value;});
$$('[data-workflow]').forEach(root=>{let timer=null;const run=$('[data-run-workflow]',root),steps=$$('[data-step]',root),status=$('.workflow-status',root);const reset=()=>{clearTimeout(timer);timer=null;run.disabled=false;steps.forEach(s=>{s.classList.remove('complete','review');$('.step-state',s).textContent='Waiting';});status.textContent='A sample enquiry is ready. Run the example to follow its journey.';};run.addEventListener('click',()=>{reset();run.disabled=true;let i=0;const next=()=>{const step=steps[i];if(i===4){step.classList.add('review');$('.step-state',step).textContent='Human review';status.textContent='Draft ready for human review. The demo stops here—nothing has been sent.';run.disabled=false;return;}step.classList.add('complete');$('.step-state',step).textContent='Complete';status.textContent=['Sample enquiry received.','Required details checked.','Owner assigned with the enquiry context.','A response draft is ready.'][i];i++;timer=setTimeout(next,550);};next();});$('[data-reset-workflow]',root).addEventListener('click',reset);});
// Submit only after useful validation. A provider outage is never reported as delivery.
const form=$('[data-contact-form]');if(form){const message=$('#message',form);message.addEventListener('input',()=>{$('[data-char-count]',form).textContent=`${message.value.length} / 2000`;});const params=new URLSearchParams(location.search);const topic=params.get('topic');if(topic){const select=$('#topic',form);let option=[...select.options].find(o=>o.value===topic);if(!option){option=new Option(topic,topic);select.add(option);}select.value=topic;}
 form.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));const valid={name:String(data.name||'').trim().length>=2,email:/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(data.email||'')),message:String(data.message||'').trim().length>=20,consent:!!data.consent};const messages={name:'Please enter at least two characters for your name.',email:'Please enter a valid email address.',message:'Please describe your project in at least 20 characters.',consent:'Please agree before submitting your enquiry.'};let first;Object.entries(valid).forEach(([key,ok])=>{const field=$(`[name="${key}"]`,form),error=$(`#${key}-error`,form);field.setAttribute('aria-invalid',String(!ok));field.setAttribute('aria-describedby',`${key}-error`);error.textContent=ok?'':messages[key];if(!ok&&!first)first=field;});if(first){first.focus();return;}
 const status=$('.form-status',form),submit=$('[type=submit]',form),fallback=$('[data-mail-fallback]',form);fallback.hidden=true;submit.disabled=true;const initial=submit.innerHTML;submit.textContent='Sending your brief…';status.textContent='';data.source=location.origin+location.pathname;
 try{const response=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json().catch(()=>({}));if(!response.ok){if(response.status===400||response.status===429){status.textContent=result.error||'Please check your details and try again.';return;}throw Error('delivery-unavailable');}status.textContent='Your brief has been sent. Thank you—we’ll review it and reply to your email.';form.reset();$('[data-char-count]',form).textContent='0 / 2000';}
 catch{status.textContent='Automatic delivery is unavailable right now. Your brief has not been sent. You can open a prepared draft in your email app and send it yourself.';const body=`Name: ${data.name}\nCompany: ${data.company||''}\nTopic: ${data.topic}\nTimeline: ${data.timeline}\n\n${data.message}`;fallback.href=`mailto:contact@theimamcollective.com?subject=${encodeURIComponent('Project brief: '+data.topic)}&body=${encodeURIComponent(body)}`;fallback.hidden=false;}
 finally{submit.disabled=false;submit.innerHTML=initial;status.focus();}
 });}
$$('[data-newsletter]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const button=$('button',form),status=$('.form-status',form);button.disabled=true;status.textContent='Subscribing…';try{const r=await fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('[name=email]',form).value})});if(!r.ok)throw Error();status.textContent='You’re subscribed. Thanks for joining the field notes.';form.reset();}catch{status.textContent='Subscription is unavailable right now. You have not been subscribed. Please try again later.';}finally{button.disabled=false;}}));
})();
